@push('scripts')<script>
const list=document.getElementById('member-list');let dragged=null;list?.querySelectorAll('.member').forEach(card=>{card.addEventListener('dragstart',()=>{dragged=card;card.classList.add('dragging')});card.addEventListener('dragend',async()=>{card.classList.remove('dragging');if(!dragged)return;const order=[...list.querySelectorAll('.member')].map(x=>x.dataset.id);try{const r=await fetch('{{ route('admin.management.reorder') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({order})});if(!r.ok)throw new Error();}catch(e){location.reload()}dragged=null});card.addEventListener('dragover',e=>{e.preventDefault();if(!dragged||dragged===card)return;const rect=card.getBoundingClientRect();if(e.clientY<rect.top+rect.height/2)card.before(dragged);else card.after(dragged)})});
</script>@endpush
